pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        Recorder rec = new Recorder();
        address caddress = address(rec);

        bool ok = true;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
        } catch {
            ok = false;
        }

        assertTrue(ok && rec.callCount() == _tos.length, "reference must call transferFrom exactly once per recipient");
    }
}

contract Recorder {
    uint256 public callCount;

    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        return true;
    }

    fallback() external payable { revert(); }
}
